     "path": "critical-finding-instant-notification.workflow-template.yaml",
     "kind": "Workflow",
     "url": "https://raw.githubusercontent.com/Dynatrace/community-examples/main/workflows/kubernetes-threat-detection/critical-finding-instant-notification.workflow-template.yaml",
